46		infoSource metrics.HasClustersInfo,
47		db db.ArgoDB,
48		appLister v1alpha1.ApplicationNamespaceLister,
49		cache *appstatecache.Cache,
50		clusterFilter func(cluster *appv1.Cluster) bool,
